INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 3, 'Indicative multi-year emissions trajectory or budget', 'Table 4 row 1', 'If applicable, an indicative multi-year emissions trajectory, trajectories or budget for its NDC implementation period', 'Only relevant if the country has a single-year NDC target and chooses to adopt an indicative multi-year emissions trajectory, trajectories or budget under paragraph 7 of the Annex to decision Decision 5/CMA.3.');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 4, 'Multi-year trajectory or budget consistent with the NDC', 'Table 4 row 2', 'If applicable, multi-year emissions trajectory, trajectories or budget for its NDC implementation period that is consistent with the NDC', 'Only relevant if the country has a multi-year NDC target.');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 5, 'Annual emissions and removals covered by the NDC', 'Table 4 row 3', 'Annual anthropogenic emissions by sources and removals by sinks covered by its NDC or, where applicable, from the emission or sink categories as identified by the host Party pursuant to paragraph 10 of annex to decision 2/CMA.3', 'To be filled out based on the country''s national GHG inventory');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 6, 'Annual emissions and removals, paragraph 10 portion', 'Table 4 row 4', 'Annual anthropogenic emissions by sources and removals by sinks covered by its NDC or, where applicable, from the portion of its NDC in accordance with paragraph 10, annex to decision 2/CMA.3', 'To be filled out based on the country''s national GHG inventory');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 7, 'Annual quantity of ITMOs first transferred', 'Table 4 row 5', 'Annual quantity of ITMOs first transferred', 'The total amount of first transfers in each year. It includes mitigation outcomes authorised for NDC use, or for NDC use and (O)IMP. Where authorised only for NDC use, it reflects the year of first international transfer. Where authorised for NDC use and (O)IMP, it reflects the earlier of first international transfer or the first transfer definition, as defined in the authorisation.');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 8, 'Outcomes authorised for (O)IMP only', 'Table 4 row 6', 'Annual quantity of mitigation outcomes authorized for use for other international mitigation purposes and entities authorized to use such mitigation outcomes, as appropriate', 'The amount of first transferred mitigation outcomes only authorised for OIMP for each year, consistent with the host country''s definition of first transfer in its authorisation. Note that where the first transfer definition is ''Authorisation'', then the tool considers issuances that occur after the year of authorisation to have been first transferred in the year of authorisation.');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 9, 'ITMOs used towards achievement of the NDC', 'Table 4 row 7', 'Annual quantity of ITMOs used towards achievement of the NDC', 'Countries should include ITMOs authorised by other countries that have been used towards their NDC target that year.');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 10, 'Net annual quantity of ITMOs', 'Table 4 row 8', 'Net annual quantity of ITMOs resulting from paras. 23(c)-(e), annex to decision 2/CMA.3', 'This is the sum of row 7 (annual quantity of ITMOs first transferred) and row 8 (first transferred mitigation outcomes authorised for (O)IMP) minus row 9 (annual quantity of ITMOs used towards NDC achievement).');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 11, 'Cumulative ITMOs divided by elapsed years', 'Table 4 row 9', 'If applicable, the cumulative amount of ITMOs, divided by the number of elapsed years in the NDC implementation period', 'This row only populates if the country has chosen the averaging approach as the accounting method. This tool assumes that elapsed years equate to the number of years for which a GHG inventory figure has been reported, and therefore corresponding adjustments can be applied, rather than the total number of years elapsed since the start of the NDC implementation period. Reporting countries should verify this approach against any guidance issued by their designated national authority and adjust the average figure accordingly.');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 12, 'Total quantitative corresponding adjustments', 'Table 4 row 10', 'Total quantitative corresponding adjustments used to calculate the emissions balance referred to in para. 23(k)(i), annex to decision 2/CMA.3, in accordance with the Party’s method for applying corresponding adjustments consistent with section III.B, annex to decision 2/CMA.3', 'Where a country has a single-year target and applies the averaging approach, this row shows the average value of the net ITMOs (row 10). Where a country has either a multi-year NDC target, or a single-year target with an indicative trajectory, this gives annual adjustments, with additions for the years in which the mitigation occurred (i.e., the vintage of the ITMO), as per Para 8(a) of the Annex to Decision 2/CMA.3.');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 13, 'Cumulative information on annual ITMO quantities', 'Table 4 row 11', 'The cumulative information in respect of the annual information in para. 23(f), annex to decision 2/CMA.3, as applicable', 'This row shows the cumulative total of the net annual quantity of ITMOs (row 10).');
INSERT INTO table4_rows (snapshot_id, row_no, short, src, full_label, explanation) VALUES ('2026-08-14', 14, 'Annual emissions balance', 'Table 4 row 12', 'For metrics in tonnes of CO2 eq. or non-GHG, an annual emissions balance consistent with chapter III.B', 'This row shows the emissions balance for years for which a GHG inventory number has been included in row 5. The emissions balance is the net balance, i.e., the sum of GHG inventory emissions (row 5) and total corresponding adjustments (row 12). Emissions balances will only show for the latest year for which there is a GHG inventory figure; remaining cells will be blank.');
INSERT INTO party_notes (snapshot_id, party, note, sources) VALUES ('2026-08-14', 'Zimbabwe', 'The first transfer definition in the authorisation associated with CA0011 is ''cancellation/use''. As part of the Technical Expert Review process, Zimbabwe confirmed the following: "“Cancellation” in this instance therefore refers to the cancellation of a transactional record on the ZCR [Zimbabwe Carbon Registry] and not to the use or retirement of the credit. The Party [Zimbabwe] explained that the cancellation of a transactional record on the ZCR does not automatically trigger a corresponding adjustment, but is rather a precondition for successfully completing an inter-registry transfer. Instead, the inter-registry transfer itself automatically triggers a corresponding adjustment." From the perspective of programme receiving the inter-registry transfer, this would be captured at the point of re-issuance of the credit on the programme''s registry. Solely for the purposes of this tool, therefore, the OIMP first transfer definition is listed as ''Issuance'', to ensure these authorisated mitigation outcomes are calculated correctly.', 'TER Report: https://unfccc.int/sites/default/files/resource/irterr2025_ZWEa01.pdf');
INSERT INTO party_notes (snapshot_id, party, note, sources) VALUES ('2026-08-14', 'Gambia & Sierra Leone', 'Both countries have indicated in their authorisation that ''first international transfer'' is to be considered the first transfer condition. As per Verra''s current approach, unless otherwise notified by the authorising government, ''first international transfer'' will be considered to have occurred at the point of retirement of the VCU. For Gambia, retirements have occurred under project 4000; for Sierra Leone, no authorized VCUs have yet been retired, and no first transfer is considered to have taken place. Verra understands, based on informal discussions, issuance may be considered the first transfer condition by these governments. As such, these countries may ultimately elect to apply corresponding adjustments to these units. Absent formal notification, data does not currently populate for Gambia or Sierra Leone in this report.', NULL);
